if set(ROWS) != set(LANGUAGES):
    raise RuntimeError("My Posts translations are missing a supported locale.")
for locale, values in ROWS.items():
    if len(values) != len(KEYS):
        raise RuntimeError(f"My Posts translation mismatch for {locale}: {len(values)}")
CATALOG = {locale: dict(zip(KEYS, row, strict=True)) for locale, row in ROWS.items()}


def translate_my_posts(language: str | None, key: str, **values: object) -> str:
    locale = normalize_language(language)
    template = CATALOG[locale].get(key, key)
    try:
        return template.format(**values)
    except (KeyError, ValueError):
        return template
